import{_ as t,o as s,c as n,a2 as o}from"./chunks/framework.CsGzzEsd.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/Quiz/C0 Ethics/misses.md","filePath":"blogs/CFA/Quiz/C0 Ethics/misses.md"}'),a={name:"blogs/CFA/Quiz/C0 Ethics/misses.md"};function r(i,e,l,c,d,p){return s(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="_2026-10-12-—-i-a-knowledge-of-the-law" tabindex="-1">2026-10-12 — I(A) Knowledge of the Law <a class="header-anchor" href="#_2026-10-12-—-i-a-knowledge-of-the-law" aria-label="Permalink to &quot;2026-10-12 — I(A) Knowledge of the Law&quot;">​</a></h2><p><strong>Q:</strong> When applicable law and the Code &amp; Standards conflict, which do you follow — and what’s the one-line rule?</p><p><strong>My answer:</strong> Follow the stricter. (Did not know the one-line rule.)</p><p><strong>Correct:</strong> Follow the <strong>stricter</strong> of applicable law vs Code &amp; Standards. One-line rule: <em>Know and comply with the stricter requirement; do not knowingly assist in any violation — dissociate if necessary.</em></p><p><strong>Gap:</strong> One-line rule / dissociation framing incomplete.</p><h2 id="_2026-10-12-—-i-a-ns-ls-ms-map" tabindex="-1">2026-10-12 — I(A) NS / LS / MS map <a class="header-anchor" href="#_2026-10-12-—-i-a-ns-ls-ms-map" aria-label="Permalink to &quot;2026-10-12 — I(A) NS / LS / MS map&quot;">​</a></h2><p><strong>Q:</strong> In a multi-jurisdiction setting, what do NS / LS / MS mean for which rule you follow?</p><p><strong>My answer:</strong> No securities law / Less strict / More strict. “The MS one.”</p><p><strong>Correct map:</strong></p><ul><li><strong>NS</strong> (no applicable securities law) → follow <strong>Code &amp; Standards</strong></li><li><strong>LS</strong> (law less strict than Code) → follow <strong>Code &amp; Standards</strong></li><li><strong>MS</strong> (law more strict than Code) → follow <strong>the law</strong></li></ul><p><strong>Gap:</strong> Named the acronyms but did not state which rule applies in each case (only gestured at MS).</p><h2 id="_2026-10-12-—-i-b-gifts-vs-inducements-ipo-allocations" tabindex="-1">2026-10-12 — I(B) Gifts vs inducements / IPO allocations <a class="header-anchor" href="#_2026-10-12-—-i-b-gifts-vs-inducements-ipo-allocations" aria-label="Permalink to &quot;2026-10-12 — I(B) Gifts vs inducements / IPO allocations&quot;">​</a></h2><p><strong>Q:</strong> Client gifts vs third-party inducements — what’s allowed, and are personal allocations from oversubscribed IPOs OK?</p><p><strong>My answer:</strong> Depends on value; key is not damaging independence. Expensive client gifts before work generally not OK; after work may be OK with disclosure + boss approval (loyalty). Third-party expensive gifts generally not OK.</p><p><strong>Correct extras:</strong></p><ul><li>Client gifts: often OK if disclosed / within policy and do not compromise independence; timing and size matter.</li><li>Third-party inducements: presume conflict — decline / firm policy; especially if meant to influence.</li><li><strong>Personal allocations from oversubscribed IPOs: banned</strong> (not an OK “gift”).</li></ul><p><strong>Gap:</strong> Did not address the IPO allocation ban.</p><h2 id="_2026-10-12-—-i-b-issuer-paid-research" tabindex="-1">2026-10-12 — I(B) Issuer-paid research <a class="header-anchor" href="#_2026-10-12-—-i-b-issuer-paid-research" aria-label="Permalink to &quot;2026-10-12 — I(B) Issuer-paid research&quot;">​</a></h2><p><strong>Q:</strong> Issuer-paid research — what fee arrangement is acceptable, and what’s the independence trap?</p><p><strong>My answer:</strong> Necessary items like normal travel/accommodation OK; obvious “gifts” not OK. Did not know the trap. (Answered travel/gifts instead of issuer-paid research.)</p><p><strong>Correct:</strong></p><ul><li>Acceptable: <strong>flat fee</strong> only (not contingent on conclusions / rating).</li><li>Trap: pay tied to favorable research, or compensation structure that buys the opinion (pay-to-play). Disclose issuer-paid nature.</li></ul><p><strong>Gap:</strong> Missed flat-fee rule and contingent-fee independence trap; conflated with travel/gift rules.</p>',23)])])}const u=t(a,[["render",r]]);export{h as __pageData,u as default};
